class Solution:
    def divisibleTripletCount(self, nums: list[int], d: int) -> int:
        from collections import defaultdict
        count = defaultdict(int)
        ans = 0
        n = len(nums)
        for j in range(n):
            for k in range(j + 1, n):
                rem = (d - (nums[j] + nums[k]) % d) % d
                ans += count[rem]
            count[nums[j] % d] += 1
        return ans

#include <vector>

class Solution {
public:
    int divisibleTripletCount(std::vector<int>& nums, int d) {
        int count[1005] = {0};
        int ans = 0;
        int n = nums.size();
        for (int j = 0; j < n; ++j) {
            for (int k = j + 1; k < n; ++k) {
                int rem = (d - (nums[j] + nums[k]) % d) % d;
                ans += count[rem];
            }
            count[nums[j] % d]++;
        }
        return ans;
    }
};

class Solution {
    public int divisibleTripletCount(int[] nums, int d) {
