        int ans = 0;
        int n = nums.length;
        for (int j = 0; j < n; j++) {
            for (int k = j + 1; k < n; k++) {
                int rem = (d - (nums[j] + nums[k]) % d) % d;
                ans += count[rem];
            }
            count[nums[j] % d]++;
